import { MeshStandardNodeMaterial } from 'three/webgpu';
import { vec4, color, uv, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight } = ctx.THREE;

  const group = new Group();

  const width = 2.4;
  const height = 0.8;
  const cardGeometry = new PlaneGeometry(width, height);

  // Load the machined metal texture
  const material = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.5,
    transparent: true,
  });

  // Base procedural subtle grain & gradient shader nodes
  const uvs = uv();
  const gradient = smoothstep(0.0, 1.0, uvs.y);
  const baseColor = color(config.colors?.surface || '#0b0b10');
  const inkColor = color(config.colors?.ink || '#16161d');
  material.colorNode = vec4(mix(inkColor, baseColor, gradient), 0.95);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.roughnessMap = tex;
      material.metalnessMap = tex;
      material.needsUpdate = true;
    }).catch((err) => {
      console.warn('Failed to load brushed metal texture', err);
    });
  }

  const cardMesh = new Mesh(cardGeometry, material);
  group.add(cardMesh);

  // Add local accent line (Signal Red) at the left border of the label
  const accentGeometry = new PlaneGeometry(0.04, height - 0.16);
  const accentMaterial = new MeshStandardNodeMaterial({
    color: config.colors?.accent || '#ff2a38',
    roughness: 0.2,
    metalness: 0.1,
  });
  const accentMesh = new Mesh(accentGeometry, accentMaterial);
  accentMesh.position.set(-width / 2 + 0.1, 0, 0.01);
  group.add(accentMesh);

  // Text setup
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textString = textItems[0]?.text ?? 'Journal 1';

  // Translate 39px font size to scene-unit em height (roughly 0.15 for 39px in this scale)
  const fontPt = 0.15;
  const textObj = ctx.fontAtlas.createText(textString, {
    fontSize: fontPt,
    color: config.colors?.paper || '#e8ecf2',
    align: 'left',
  });
  textObj.position.set(-width / 2 + 0.22, -0.05, 0.02);
  group.add(textObj);

  // Subtle directional lighting to pop the machined surface
  const localLight = new DirectionalLight(config.colors?.accent || '#ff2a38', 0.8);
  localLight.position.set(-2, 1, 3);
  group.add(localLight);

  // Entrance animation
  const tl = gsap.timeline();
  tl.fromTo(
    group.position,
    { y: group.position.y - 0.2, x: group.position.x },
    { y: group.position.y, x: group.position.x, duration: 0.8, ease: 'power3.out' }
  );

  // Primitive registration placeholder
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const inst = ctx.primitives[prim.name](group, prim.params);
        if (inst) activePrimitives.push(inst);
      }
    });
  }

  // Cleanup handler
  group.userData = {
    handlers: {},
    cleanup: () => {
      tl.kill();
      cardGeometry.dispose();
      material.dispose();
      accentGeometry.dispose();
      accentMaterial.dispose();
      localLight.dispose();
      activePrimitives.forEach((p) => p.cleanup && p.cleanup());
    },
  };

  return group;
}
